import { expect, test } from 'bun:test';
import { renderToStaticMarkup } from 'react-dom/server';

import i18n from '../../i18n/index';
import type { DecisionItem as DecisionItemType } from '../../types/conversation';
import { DecisionItem } from './DecisionItem';

const BASE: DecisionItemType = {
  id: 'item-1',
  prompt: 'Which option?',
  status: 'pending',
  kind: 'decision',
  options: [
    { id: 'opt-a', label: 'Option A' },
    { id: 'opt-b', label: 'Option B' },
  ],
};

async function render(item: DecisionItemType) {
  await i18n.changeLanguage('fr');
  return renderToStaticMarkup(<DecisionItem item={item} index={0} onChange={() => {}} />);
}

test('no response → badge absent, options enabled', async () => {
  const html = await render(BASE);
  expect(html).not.toContain("Résolu depuis l&#x27;app");
  expect(html).not.toContain('disabled=""');
});

test('human response (no mirroredFromApprovalId) → badge absent, options locked', async () => {
  const html = await render({ ...BASE, status: 'answered', response: { selectedOptionIds: ['opt-a'] } });
  expect(html).not.toContain("Résolu depuis l&#x27;app");
  expect((html.match(/disabled=""/g) ?? []).length).toBe(2);
});
