/**
 * Persistance de l'état de vue (filtres, onglets, recherche, tri, replis…) —
 * logique PURE, sans dépendance React ni accès direct à `window`.
 *
 * Trois niveaux (voir docs du chantier persistance-filtres-onglets-ui) :
 *   - `storage: 'url'`     → URL search params (routable, partageable), avec
 *                            une copie en `sessionStorage` comme filet.
 *   - `storage: 'session'` → `sessionStorage` seul (états verbeux/ergonomiques,
 *                            ex. `collapsedProjects: Record<string, boolean>`).
 *   - localStorage (préférences durables) est hors périmètre de ce module.
 *
 * Précédence par clé, au montage : URL > sessionStorage > défaut. Toute
 * valeur restaurée est validée ; une valeur invalide (ou un storage qui jette,
 * ex. navigation privée stricte) ne provoque jamais d'exception — elle
 * dégrade silencieusement vers la clé de repli suivante, puis vers le défaut.
 *
 * Le storage (session) est injecté en paramètre — jamais `window.sessionStorage`
 * en dur ici — pour rester testable sans DOM (cf. le style try/catch de
 * `src/components/NotificationCenter.tsx` / `src/hooks/useDesktopNotifications.ts`).
 */

/** Sous-ensemble de `Storage` (DOM) suffisant pour l'injection en test. */
export interface ViewStateStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

/**
 * Valide une valeur candidate (déjà parsée) : soit une liste d'énum, soit un
 * prédicat borné. Reçoit `unknown` — la valeur peut venir d'une URL ou d'un
 * JSON.parse de sessionStorage, donc jamais garantie du bon type a priori.
 */
export type ViewStateValidate<V> = readonly V[] | ((value: unknown) => boolean);

export interface ViewStateFieldSpec<V> {
  /**
   * Nom de la clé dans l'URL (`storage: 'url'`) ou dans le sessionStorage
   * (`storage: 'session'`). Par défaut : le nom de la clé de la spec.
   */
  urlKey?: string;
