}

/** Primitive générique : lit une clé sessionStorage typée, avec repli. */
export function readSession<V>(session: ViewStateStorage, key: string, fallback: V): V {
  const { present, value } = readSessionRaw(session, key);
  return present ? (value as V) : fallback;
