1	import { expect, test } from 'bun:test';
2	
3	import { toggleSelection } from './dropdownSelection';
4	
5	test('ajoute une valeur absente sous la limite', () => {
6	  expect(toggleSelection(['a', 'b'], 'c', 4)).toEqual(['a', 'b', 'c']);
7	});
8	
9	test('retire une valeur présente', () => {
10	  expect(toggleSelection(['a', 'b', 'c'], 'b', 4)).toEqual(['a', 'c']);
11	});
12	
13	test('no-op à la limite avec une valeur absente', () => {
14	  expect(toggleSelection(['a', 'b', 'c', 'd'], 'e', 4)).toEqual(['a', 'b', 'c', 'd']);
15	});
16	
17	test('le retrait fonctionne même à la limite (une valeur présente reste toujours retirable)', () => {
18	  expect(toggleSelection(['a', 'b', 'c', 'd'], 'c', 4)).toEqual(['a', 'b', 'd']);
19	});
20	
21	test('tableau vide en entrée', () => {
22	  expect(toggleSelection([], 'a', 4)).toEqual(['a']);
23	});
24	
25	test('max = 0 : aucun ajout possible, mais un retrait reste toujours permis', () => {
26	  expect(toggleSelection([], 'a', 0)).toEqual([]);
27	  expect(toggleSelection(['a'], 'a', 0)).toEqual([]);
28	  expect(toggleSelection(['a'], 'b', 0)).toEqual(['a']);
29	});
30	
31	test('immutabilité : le tableau reçu en argument n\'est jamais modifié en place', () => {
32	  const addInput = ['a', 'b'];
33	  const addResult = toggleSelection(addInput, 'c', 4);
34	  expect(addInput).toEqual(['a', 'b']);
35	  expect(addResult).not.toBe(addInput);
36	
37	  const removeInput = ['a', 'b', 'c'];
38	  const removeResult = toggleSelection(removeInput, 'b', 4);
39	  expect(removeInput).toEqual(['a', 'b', 'c']);
40	  expect(removeResult).not.toBe(removeInput);
41	
42	  const noopInput = ['a', 'b', 'c', 'd'];
43	  const noopResult = toggleSelection(noopInput, 'e', 4);
44	  expect(noopInput).toEqual(['a', 'b', 'c', 'd']);
45	  expect(noopResult).toEqual(noopInput);
46	  expect(noopResult).not.toBe(noopInput);
47	});
48	
[/external_agent_tool_result]

