 * indépendante de l'ordre d'énumération de la spec. Primitive destinée à
 * servir de dépendance à un effet React dans un lot ultérieur.
 */
export function serializeManaged<T extends Record<string, unknown>>(
  spec: ViewStateSpec<T>,
  searchParams: URLSearchParams,
): string {
  const storageKeys = (Object.keys(spec) as (keyof T)[])
    .filter((key) => spec[key].storage === 'url')
    .map((key) => resolveStorageKey(key, spec[key]))
