const buttons = Array.from(document.querySelectorAll('button'));
const findChip = (label) => buttons.find(b => b.textContent.startsWith(label) && b.getAttribute('aria-pressed') !== null);
const a = findChip('groupe-gilbert');
const b = findChip('brillance-d-cor-inc');
// Deux clics synchrones dos-à-dos, SANS attendre de re-rendu entre les deux —
// simule exactement la course (deux bascules quasi simultanées).
a.click();
b.click();
JSON.stringify({ clicked: [a.textContent, b.textContent] });
"}
[/external_agent_tool_call]

