(function() {
  const getButtons = () => Array.from(document.querySelectorAll('button'));
  // Trouver le trigger du Dropdown "Projet" via son label associé.
  const labels = Array.from(document.querySelectorAll('label'));
  const projLabel = labels.find(l => l.textContent.trim() === 'Projet');
  const trigger = projLabel ? projLabel.parentElement.querySelector('button') : null;
  if (!trigger) return 'trigger introuvable';
  trigger.click();
  return trigger.textContent;
})();
"}
[/external_agent_tool_call]

